224			{Item: "浊度", Value: 2},
225			{Item: "溶氧🫧", Value: 3},
226			{Item: "ph\x00x", Value: 4},
227			{Item: "  pH  ", Value: 5},
228			{Item: "PH", Value: 6},
229		}
