260			if r.Limit != 100.0 || !r.LimitEffective.Equal(at(1, 0)) {
261				t.Fatalf("逐项限值异常: %+v", r)
262			}
263			rs[r.Item] = r
264		}
265		for _, item := range items {
266			if _, ok := rs[item]; !ok {
267				t.Fatalf("项目 %q 在确认结果中缺失: %+v", item, confirmed.Results)
268			}
269		}
270	
271		// 按点查看与返回记录一致
272		list, err := s.ListByPoint("P1")
273		if err != nil || len(list) != 1 {
274			t.Fatalf("按点查看异常: %+v err=%v", list, err)
275		}
276		listed := list[0]
277		if listed.ID != smp.ID {
278			t.Fatalf("按点查看记录不一致: %+v", listed)
279		}
280		if listed.PointID != "P1" || len(listed.Measurements) != len(items) {
281			t.Fatalf("按点查看记录不一致: %+v", listed)
282		}
283		listItems := map[string]bool{}
284		for _, m := range listed.Measurements {
285			listItems[m.Item] = true
286		}
287		for _, item := range items {
288			if !listItems[item] {
289				t.Fatalf("项目 %q 在按点查看中缺失", item)
290			}
291		}
292	
293		// 重开后保存的数据与录入时一致
294		if err := s.Close(); err != nil {
295			t.Fatalf("Close: %v", err)
296		}
297		s2, err := Open(dir)
298		if err != nil {
299			t.Fatalf("reopen: %v", err)
300		}
301		defer s2.Close()
302		reopened, err := s2.ListByPoint("P1")
303		if err != nil || len(reopened) != 1 {
304			t.Fatalf("重开后按点查看异常: %+v err=%v", reopened, err)
305		}
306		fromDisk := reopened[0]
307		if fromDisk.ID != "S-�-01" {
308			t.Fatalf("重开后记录与录入不一致: %+v", fromDisk)
309		}
310		if fromDisk.PointID != "P1" || fromDisk.Status != StatusConfirmed || len(fromDisk.Measurements) != len(items) {
311			t.Fatalf("重开后记录与录入不一致: %+v", fromDisk)
312		}
313		diskItems := map[string]bool{}
314		for _, m := range fromDisk.Measurements {
315			diskItems[m.Item] = true
316		}
317		for _, item := range items {
318			if !diskItems[item] {
319				t.Fatalf("项目 %q 在保存数据中缺失或被改写", item)
320			}
321		}
322		// 全部测量值均不超过上限 100，重开后整份结论应原样保存为达标
323		if fromDisk.Exceeded || len(fromDisk.Results) != len(items) {
324			t.Fatalf("整份结论或逐项依据在保存数据中不一致: %+v", fromDisk)
325		}
326	}
