229	// 这次名称含非法字节，也报告文本编码错误。
230	func (s *Store) RegisterPoint(id, name string) (SamplingPoint, error) {
231		s.mu.Lock()
232		defer s.mu.Unlock()
233		if err := s.checkOpenLocked(); err != nil {
234			return SamplingPoint{}, err
235		}
236		// 在去首尾空白和其它任何处理之前检查原始文本：落盘 JSON 会把非法 UTF-8
237		// 静默替换成 U+FFFD，登记“成功”后保存的编号或名称就会与填写内容对不上，
238		// 两个不同编号（如末尾分别为孤立 0xFF、0xFE）还可能变成同一编号；只有
239		// 整次拒绝才能保证采样点身份在保存前后一致。即使另一项为空白，或编号
240		// 已登记而名称含非法字节，也必须报告编码问题。
241		if invalidUTF8(id) || invalidUTF8(name) {
242			return SamplingPoint{}, ErrInvalidText
243		}
244		id, name = clean(id), clean(name)
245		if id == "" || name == "" {
246			return SamplingPoint{}, ErrEmptyField
247		}
248		if _, ok := s.points[id]; ok {
249			return SamplingPoint{}, fmt.Errorf("%w: %s", ErrDuplicatePoint, id)
250		}
251		p := SamplingPoint{ID: id, Name: name}
252		s.points[id] = p
253		if err := s.persistLocked(); err != nil {
254			delete(s.points, id)
255			return SamplingPoint{}, err
256		}
257		return p, nil
258	}
